import boto3

def check_unsafe_content(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    else:
        return False

if __name__ == '__main__':
    script_text = 'YOUR_SCRIPT_TEXT_HERE'
    if check_unsafe_content(script_text):
        print('Unsafe content detected!')
    else:
        print('No unsafe content detected.')

import boto3

def synthesize_speech(text, output_format, voice_id):
    polly_client = boto3.client('polly')
    response = polly_client.synthesize_speech(
        Text=text,
        OutputFormat=output_format,
        VoiceId=voice_id
    )
    return response

def save_speech(response, file_name):
    if 'AudioStream' in response:
        with open(file_name, 'wb') as file:
            file.write(response['AudioStream'].read())
    else:
        raise ValueError('Invalid response from Polly')

def normalize_text(text):
    return text.strip().replace('\n', ' ').replace('\t', ' ')

import boto3

def list_voices(locale):
    polly_client = boto3.client('polly')
    voices = polly_client.describe_voices(LanguageCode=locale)
    return voices['Voices']

if __name__ == '__main__':
    locale = 'en-US'  # Example locale
    voices = list_voices(locale)
    for voice in voices:
        print(voice['Name'])

